[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "video-player-dashboard",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "video-player-dashboard",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "title",
                "type": "Text",
                "properties": {
                  "content": "Video Player Dashboard",
                  "style": "titleLarge"
                }
              },
              {
                "id": "player_container",
                "type": "Card",
                "properties": {
                  "padding": {
                    "all": 0
                  },
                  "child": {
                    "id": "player_stack",
                    "type": "Stack",
                    "properties": {
                      "children": [
                        {
                          "id": "video_image",
                          "type": "Image",
                          "properties": {
                            "src": "/ui-assets/video-player-dashboard-mockup.jpg",
                            "alt": "A nature documentary video showing a deep sea creature.",
                            "fit": "cover",
                            "height": 480
                          }
                        },
                        {
                          "id": "video_title_overlay",
                          "type": "Positioned",
                          "properties": {
                            "top": 16,
                            "left": 16,
                            "child": {
                              "id": "video_title_text",
                              "type": "Text",
                              "properties": {
                                "content": "Nature Documentary: The Deep Sea",
                                "style": "titleMedium"
                              }
                            }
                          }
                        },
                        {
                          "id": "skip_intro_overlay",
                          "type": "Positioned",
                          "properties": {
                            "bottom": 80,
                            "right": 16,
                            "child": {
                              "id": "skip_intro_button",
                              "type": "Button",
                              "properties": {
                                "label": "Skip Intro"
                              }
                            }
                          }
                        },
                        {
                          "id": "next_episode_overlay",
                          "type": "Positioned",
                          "properties": {
                            "top": 0,
                            "bottom": 0,
                            "left": 0,
                            "right": 0,
                            "child": {
                              "id": "next_episode_container",
                              "type": "Column",
                              "properties": {
                                "mainAxisAlignment": "center",
                                "crossAxisAlignment": "center",
                                "children": [
                                  {
                                    "id": "next_episode_button",
                                    "type": "Button",
                                    "properties": {
                                      "label": "Next Episode: Journey to the Abyss",
                                      "variant": "filled"
                                    }
                                  }
                                ]
                              }
                            }
                          }
                        },
                        {
                          "id": "control_bar_overlay",
                          "type": "Positioned",
                          "properties": {
                            "bottom": 0,
                            "left": 0,
                            "right": 0,
                            "child": {
                              "id": "control_bar_container",
                              "type": "Box",
                              "properties": {
                                "backgroundColor": "#00000099",
                                "padding": {
                                  "horizontal": 16,
                                  "vertical": 8
                                },
                                "child": {
                                  "id": "control_bar_column",
                                  "type": "Column",
                                  "properties": {
                                    "children": [
                                      {
                                        "id": "progress_row",
                                        "type": "Row",
                                        "properties": {
                                          "verticalAlignment": "center",
                                          "spacing": 8,
                                          "children": [
                                            {
                                              "id": "current_time",
                                              "type": "Text",
                                              "properties": {
                                                "content": "02:30"
                                              }
                                            },
                                            {
                                              "id": "progress_slider",
                                              "type": "Slider",
                                              "properties": {
                                                "value": 150,
                                                "max": 2700,
                                                "expanded": true
                                              }
                                            },
                                            {
                                              "id": "total_time",
                                              "type": "Text",
                                              "properties": {
                                                "content": "45:00"
                                              }
                                            }
                                          ]
                                        }
                                      },
                                      {
                                        "id": "buttons_row",
                                        "type": "Row",
                                        "properties": {
                                          "mainAxisAlignment": "spaceBetween",
                                          "children": [
                                            {
                                              "id": "left_controls",
                                              "type": "Row",
                                              "properties": {
                                                "spacing": 8,
                                                "children": [
                                                  {
                                                    "id": "rewind_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/rewind-10.svg",
                                                      "tooltip": "Rewind 10 seconds"
                                                    }
                                                  },
                                                  {
                                                    "id": "play_pause_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/pause.svg",
                                                      "tooltip": "Pause"
                                                    }
                                                  },
                                                  {
                                                    "id": "forward_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/forward-10.svg",
                                                      "tooltip": "Fast-Forward 10 seconds"
                                                    }
                                                  }
                                                ]
                                              }
                                            },
                                            {
                                              "id": "right_controls",
                                              "type": "Row",
                                              "properties": {
                                                "spacing": 8,
                                                "children": [
                                                  {
                                                    "id": "volume_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/volume.svg",
                                                      "tooltip": "Volume"
                                                    }
                                                  },
                                                  {
                                                    "id": "subtitles_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/subtitles.svg",
                                                      "tooltip": "Subtitles/CC (English)"
                                                    }
                                                  },
                                                  {
                                                    "id": "settings_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/settings.svg",
                                                      "tooltip": "Settings"
                                                    }
                                                  },
                                                  {
                                                    "id": "fullscreen_button",
                                                    "type": "IconButton",
                                                    "properties": {
                                                      "icon": "/icons/fullscreen.svg",
                                                      "tooltip": "Fullscreen"
                                                    }
                                                  }
                                                ]
                                              }
                                            }
                                          ]
                                        }
                                      }
                                    ]
                                  }
                                }
                              }
                            }
                          }
                        }
                      ]
                    }
                  }
                }
              }
            ]
          }
        }
      ]
    }
  }
]
